theorem imo2019_p1 (f : ℤ → ℤ) :
    (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) ↔ f ∈ solution_set  := by
  constructor; swap;
  intro hf a b;
  cases' hf with hf1 hf2;
  simp [hf1];
  obtain ⟨c, hc⟩ := hf2;
  simp [hc]; ring;
  intro hf;
  have g : ∀z, ∃d, ∀z, g z = d * z := by
    intro z;
    cases z with _ | 0 | _;
    · use 0; rfl

theorem imo2019_p1 (f : ℤ → ℤ) :
    (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) ↔ f ∈ solution_set   := by
  constructor; swap
  intro hf a b; cases' hf with hf1 hf2; simp [hf1]; obtain ⟨c, hc⟩ := hf2; simp [hc]; ring
  intro hf; let g : ℤ → ℤ := fun z => f z - f 0; have hg : ∀ z, g z = f z - f 0 := by rfl;
  have : ∀ x y, g (x + y) = g x + g y := by
    intro x y; simp only [hg]; have hx := hf 0 (x + y); have hxy := hf x y; have hx0 := hf x 0;
    have h0x := hf 0 x; simp at hx hx0 h0x; omega
  cases' this with d ⟨c, hc⟩; cases' em (d = 0) with hd hd;
  case inl => left; have := by simp [hc, sub_add_cancel]; intro z; rw [← this z, hg, sub_add_cancel]; rw [hd, ‹_›, zero_mul, add_zero];

problem imo2019_p1 (f : ℤ → ℤ) :
    (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) ↔ f ∈ solution_set  := by
  constructor; swap
  intro hf a b;
  cases' hf with hf1 hf2;
  ext; simp [hf1];
  obtain ⟨c, hc⟩ := hf2;
  simp [hc];
  use f 0;
  cases' em (f 0 = 0) with hf₀ hf₀;
  suffices : f(2 * a) + 2 f(b) = f(f(a + b)) => ∀ a b, f(a) + f(b) = f(a + b) := by
    intro hf2;
    linarith [hf2];

